function generateRandomNumber() {
  return Math.floor(Math.random() * 100) + 1;
}

function generateRandomString(length) {
  let result = '';
  const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  const charactersLength = characters.length;

  for (let i = 0; i < length; i++) {
    result += characters.charAt(Math.floor(Math.random() * charactersLength));
  }

  return result;
}

function generateRandomArray(elementType, count) {
  const array = [];
  for (let i = 0; i < count; i++) {
    if (elementType === 'number') {
      array.push(generateRandomNumber());
    } else if (elementType === 'string') {
      array.push(generateRandomString(10));
    } else if (elementType === 'array') {
      array.push(generateRandomArray(elementType, generateRandomNumber(5)));
    }
  }
  return array;
}

// Example usage
console.log(generateRandomArray('number', 5)); // [47, 83, 2, 71, 56]
